(()=>{const tabs=[...document.querySelectorAll('.auth-tab')],signup=document.getElementById('signup-form'),login=document.getElementById('login-form');function mode(m){tabs.forEach(t=>t.classList.toggle('active',t.dataset.mode===m));signup.hidden=m!=='signup';login.hidden=m!=='login';history.replaceState(null,'',`/account?mode=${m}`)}tabs.forEach(t=>t.onclick=()=>mode(t.dataset.mode));const err=(input,msg)=>{const f=input.closest('.auth-field');f.classList.toggle('invalid',!!msg);f.querySelector('.field-error').textContent=msg;return !msg};const status=(form,msg,type)=>{const el=form.querySelector('.auth-status');el.textContent=msg;el.className=`auth-status show ${type}`};signup.onsubmit=e=>{e.preventDefault();const n=signup.fullName,em=signup.email,m=signup.mobile,p=signup.password,c=signup.confirm;const ok=[err(n,n.value.trim().length<2?'Enter your full name.':''),err(em,/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em.value)?'':'Enter a valid email address.'),err(m,/^[6-9]\d{9}$/.test(m.value)?'':'Enter a valid 10-digit mobile number.'),err(p,/^(?=.*[A-Za-z])(?=.*\d).{8,}$/.test(p.value)?'':'Use at least 8 characters with a letter and number.'),err(c,c.value!==p.value?'Passwords do not match.':'')].every(Boolean);if(ok)status(signup,'Details validated successfully. Your account service can now process this signup.','success')};login.onsubmit=e=>{e.preventDefault();const i=login.identifier,p=login.password;const validId=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(i.value)||/^[6-9]\d{9}$/.test(i.value);if([err(i,validId?'':'Enter a valid email or mobile number.'),err(p,p.value?'':'Enter your password.')].every(Boolean))status(login,'Login details validated successfully.','success')};document.getElementById('forgot-password').onclick=()=>{const i=login.identifier;if(err(i,i.value?'':'Enter your email or mobile number first.'))status(login,'If an account exists, password-reset instructions will be sent securely.','success')};mode(new URLSearchParams(location.search).get('mode')==='login'?'login':'signup')})();
